import{t as e}from"./evaluation-7ywiHJmR.js";var t=(()=>{let t=[],n=0,r=0,i=0,a=0;function o(e,o,s){n=Math.min(e,o)/2*.9,r=n/s,t=[];for(let e=0;e<s;e++)t.push({radius:n-e*r,parent:e===0?null:e-1});i=e,a=o}function s(n,r,s,c){let l=r.width,u=r.height,d=l/2,f=u/2;(t.length!==s.circleCount||i!==l||a!==u)&&o(l,u,s.circleCount),n.fillStyle=`#000000`,n.fillRect(0,0,l,u);let p=c/s.cycleFrames*e,m=Math.cos(p),h=Math.sin(p),g=Array(t.length);g[0]={x:d,y:f,rotation:0};for(let e=1;e<t.length;e++){let n=g[e-1],r=t[e-1].radius-t[e].radius;g[e]={x:n.x+r*m,y:n.y+r*h,rotation:p}}let _=(s.displayMode||`lines`).toLowerCase();if(_===`lines`){n.strokeStyle=`#ffffff`,n.lineWidth=1,n.beginPath();for(let r=0;r<t.length;r++){let i=t[r].radius,{x:a,y:o}=g[r];n.moveTo(a,o),n.lineTo(a+i*m,o+i*h),n.moveTo(a+i,o),n.arc(a,o,i,0,e)}n.stroke()}else if(_===`b/w`)for(let r=t.length-1;r>=0;r--)n.fillStyle=r%2==0?`#ffffff`:`#000000`,n.beginPath(),n.arc(g[r].x,g[r].y,t[r].radius,0,e),n.fill();else if(_===`gradient`)for(let r=t.length-1;r>=0;r--)n.fillStyle=`rgba(255, 255, 255, ${1-r/t.length*.7})`,n.beginPath(),n.arc(g[r].x,g[r].y,t[r].radius,0,e),n.fill()}return{id:`circles`,title:`Nested Circles`,category:`other`,description:`Nested circles chain animating as a single rotating arm. Three rendering modes: outline (Lines), alternating fill (B/W), and alpha-depth fill (Gradient).`,version:`1.0.0`,infoSections:[{heading:`DESCRIPTION`,body:`Circles renders circleCount nested circles where each inner circle orbits inside its parent at a uniform angular rate. The outermost circle is stationary at the canvas centre; each successive inner circle orbits at the same orbitAngle, forming a chain that rotates as a single rigid arm — not epicyclic rolling motion. Three rendering modes: Lines draws each circle as a white arc outline with a radial spoke from centre to edge; B/W fills circles outermost to innermost with alternating black and white; Gradient fills outermost to innermost with white at decreasing alpha (1 − (i/count) × 0.7), producing a translucent depth effect. The generator uses a fixed 800×800 canvas with a 2d context. Outer radius is derived from canvas size as min(W,H)/2 × 0.9 and is not user-configurable.`},{heading:`ALGORITHM`,body:`Two functions: initCircles(width, height, count) and draw(ctx, canvas, params, frame). initCircles: largestRadius = min(W,H)/2×0.9; radiusDecrement = largestRadius/count; circle_i = { radius: largestRadius − i×radiusDecrement, parent: i−1 } for i = 0..count−1 (circle_0.parent = null). Rebuild triggers when circleCount changes or canvas dimensions change. draw: computes orbitAngle = (frame/cycleFrames)×2π; cosA = cos(orbitAngle) and sinA = sin(orbitAngle) computed once per frame and shared across all circles. Transform chain: transforms[0] = (cx, cy, 0); for i > 0: orbitRadius_i = circle_{i-1}.radius − circle_i.radius; transforms[i] = { x: transforms[i-1].x + orbitRadius_i×cosA, y: transforms[i-1].y + orbitRadius_i×sinA, rotation: orbitAngle }. This telescopes to x_i = cx + (radius_0 − radius_i)×cosA. Lines mode: single batched path — per circle: moveTo(x,y), lineTo(x+r×cosA, y+r×sinA) for spoke; moveTo(x+r,y), arc(x,y,r,0,2π) for outline; single ctx.stroke() for all circles. B/W mode: back-to-front fill; fillStyle = (i%2===0) ? white : black. Gradient mode: back-to-front; alpha = 1−(i/count)×0.7; rgba fill.`},{heading:`PARAMETERS`,body:`Display group — displayMode: radio, options Lines|B/W|Gradient, default Lines; selects the rendering style applied each frame. Animation group — circleCount: slider, range 10–200, step 1, default 100; number of circles in the orbital chain; changing this value triggers a full rebuild of the circles array. cycleFrames: slider, range 600–7200, step 60, default 3600; frames per full revolution (3600 frames = 60 seconds at 60 FPS = one revolution per minute); controls orbit speed without changing geometry.`},{heading:`PRESETS`,body:`No presets defined. Default state: 100 circles, 3600-frame cycle, Lines mode produces a white nested-arc arm rotating once per minute against a black background.`},{heading:`PERFORMANCE`,body:`Complexity: O(circleCount) — linear. Dominant operation: circleCount arc draw calls per frame. At default (100 circles, Lines mode): <1 ms. At maximum (200 circles, Lines mode): ~400 canvas operations, estimated 1–3 ms. Well within 16.7 ms frame budget at all parameter values. Compute tier: lightweight — no adaptive resolution or worker offload required. Optimisations applied: cosA/sinA computed once per frame and shared across all circles (eliminates per-circle cos/sin calls); Lines mode batches all subpaths into a single ctx.beginPath() … ctx.stroke() sequence, eliminating per-circle ctx.save()/ctx.restore() overhead. Rebuild cost: O(circleCount) JS object allocation; triggered only on circleCount or canvas size change.`},{heading:`ANIMATION`,body:`Type: loop. loopFrames: 3600, matching the cycleFrames default; one full revolution per minute at 60 FPS. loopFrames is a static config field — if cycleFrames is changed by the user, the export period (loopFrames) does not update automatically. Fully deterministic: same frame index and same params always produce identical output. No Math.random, no accumulated state, no Date.now dependency. Export-compatible for PNG, GIF (3600-frame loop at 60 FPS), WebM, and frame sequence. Sequencer disabled: no animatable phase parameters exist; animation is purely frame-driven.`},{heading:`KNOWN LIMITATIONS`,body:`Play/pause control not implemented at the script level; control is host-provided only. Outer radius not user-configurable; always derived from canvas size as min(W,H)/2×0.9. Line width hardcoded to 1; no slider available. Stroke and fill colours hardcoded (white on black); no colour customisation. If cycleFrames is changed from its default (3600), exported GIF and sequence will span loopFrames (3600) frames rather than the actual cycle period. Orbit model uses uniform angular rate for all circles, producing rigid-arm rotation rather than epicyclic (rolling) motion; inner circles do not complete additional revolutions relative to outer circles.`},{heading:`REFERENCES`,body:`Algorithm: hierarchical circular orbital chain with uniform angular rate. No named published algorithm; standard parameterised circular orbit geometry.`}],compute:{cost:`lightweight`},canvas:{width:800,height:800,context:`2d`,background:`#000000`},parameters:[{group:`Display`,params:[{key:`displayMode`,type:`radio`,label:`Mode`,options:[`Lines`,`B/W`,`Gradient`],default:`Lines`}]},{group:`Animation`,params:[{key:`circleCount`,type:`slider`,label:`Circle Count`,min:10,max:200,step:1,default:100},{key:`cycleFrames`,type:`slider`,label:`Cycle Speed`,min:600,max:7200,step:60,default:3600}]}],animation:{type:`loop`,loopFrames:3600,defaultFps:60,animatableParams:[],sequencer:!1,animationExport:!0},export:{png:!0,gif:!0,webm:!0,sequence:!0},draw:s}})();export{t as SCRIPT_CONFIG};